import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { createRequire } from 'node:module';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const browser = await chromium.launch({ headless: true, args: ['--disable-background-timer-throttling', '--disable-renderer-backgrounding'] });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', (e) => { errors.push(e.message); console.log('PAGEERROR', e.message); });
page.on('console', (m) => { if (m.type() === 'error') console.log('CONSOLE-ERR', m.text()); });
await page.goto('http://localhost:3000', { waitUntil: 'load' });
await page.waitForTimeout(700);

const results = await page.evaluate(() => {
  const H = window.shadowHeist;
  const out = [];
  const test = (name, fn) => {
    try {
      const r = fn();
      out.push({ name, pass: r === true || (r && r.pass !== false), detail: r === true ? '' : (r && r.detail) || '' });
    } catch (e) {
      out.push({ name, pass: false, detail: e.message });
    }
  };
  const D = (ax, ay, bx, by) => Math.hypot(bx - ax, by - ay);
  H.sound.enabled = false;
  H.startMission(0);
  H.state = 'playing';

  test('mission-01 loads with spawn on floor', () => {
    H.startMission(0);
    const p = H.player;
    return { pass: H.level && H.state === 'playing' && H.isFloorPx(p.x, p.y), detail: `spawn ${p.x.toFixed(0)},${p.y.toFixed(0)}` };
  });

  test('guard vision raises awareness and triggers chase', () => {
    H.startMission(0);
    const g = H.level.guards[0];
    g.state = 'patrol'; g.awareness = 0; g.angle = 0;
    const p = H.player;
    p.hidden = false; p.crouching = false;
    p.x = g.x + 120; p.y = g.y;
    const saw = H.guardSeesPlayer(g);
    for (let i = 0; i < 40; i++) { H.time += 0.033; H.updateGuard(g, 0.033); }
    H.time += 0.001;
    return { pass: saw && (g.state === 'chase' || g.state === 'suspicious') && g.awareness > 0.3, detail: `seen=${saw} state=${g.state} awareness=${g.awareness.toFixed(2)}` };
  });

  test('hiding blocks guard vision', () => {
    H.startMission(0);
    const g = H.level.guards[0];
    g.state = 'patrol'; g.awareness = 0; g.angle = 0;
    const p = H.player;
    p.hidden = true;
    p.x = g.x + 80; p.y = g.y;
    const sees = H.guardSeesPlayer(g);
    return { pass: sees === false, detail: `hidden sees=${sees}` };
  });

  test('vent concealment blocks guard vision', () => {
    H.startMission(0);
    const g = H.level.guards[0];
    g.angle = 0;
    const p = H.player;
    p.hidden = false;
    // mission 0 vent at tile 12,21 through 21,21
    p.x = (15.5) * 40; p.y = (21.5) * 40;
    g.x = p.x - 60; g.y = p.y;
    const sees = H.guardSeesPlayer(g);
    return { pass: sees === false, detail: `inVent=${H.isVent(15, 21)} sees=${sees}` };
  });

  test('camera sweeps, gains confidence and raises alarm', () => {
    H.startMission(0);
    const cam = H.level.cameras[0];
    cam.sweep = 0; cam.angle = 0; cam.confidence = 0; cam.alarmCooldown = 0; cam.beeped = false;
    const p = H.player;
    p.hidden = false; p.crouching = false;
    p.x = cam.px + 90; p.y = cam.py;
    const before = H.alert;
    let saw = false;
    for (let i = 0; i < 80; i++) { H.time += 0.033; H.updateCamera(cam, 0.033); if (cam.confidence > 0) saw = true; }
    return { pass: saw && H.alert > before && cam.alarmCooldown > 0, detail: `saw=${saw} alert ${before.toFixed(1)}→${H.alert.toFixed(1)} cooldown=${cam.alarmCooldown.toFixed(1)}` };
  });

  test('laser breach raises alert and knocks player back', () => {
    H.startMission(1);
    const laser = H.level.lasers[0];
    laser.phase = 0; laser.period = 100; laser.duty = 1; laser.hitCooldown = 0;
    const p = H.player;
    p.hidden = false; p.crouching = false;
    p.x = (laser.x1p + laser.x2p) / 2; p.y = laser.y1p;
    const x0 = p.x;
    const before = H.alert;
    H.time += 0.01;
    H.updateLasers(0.016);
    return { pass: H.alert > before && Math.abs(p.x - x0) > 2, detail: `alert ${before.toFixed(1)}→${H.alert.toFixed(1)} dx=${(p.x - x0).toFixed(1)}` };
  });

  test('low laser is safe while crouching', () => {
    H.startMission(1);
    const laser = H.level.lasers[2];
    laser.phase = 0; laser.period = 100; laser.duty = 1; laser.hitCooldown = 0;
    const p = H.player;
    p.hidden = false; p.crouching = true;
    p.x = (laser.x1p + laser.x2p) / 2; p.y = laser.y1p;
    const before = H.alert;
    H.time += 0.01;
    H.updateLasers(0.016);
    return { pass: H.alert === before, detail: `low=${laser.low} crouch=${p.crouching} alert ${before.toFixed(1)}→${H.alert.toFixed(1)}` };
  });

  test('terminal disables cameras for 18s', () => {
    H.startMission(1);
    const t = H.level.terminals.find((x) => x.disables === 'cameras');
    const p = H.player;
    p.x = t.px; p.y = t.py; p.hidden = false;
    H.time = 0;
    H.updateInteraction();
    const kind = H.interactable && H.interactable.kind;
    H.interact();
    return { pass: kind === 'terminal' && H.level.camerasDisabledUntil >= H.time + 17, detail: `kind=${kind} until=${H.level.camerasDisabledUntil.toFixed(1)}` };
  });

  test('terminal disables lasers for 18s', () => {
    H.startMission(1);
    const t = H.level.terminals.find((x) => x.disables === 'lasers');
    const p = H.player;
    p.x = t.px; p.y = t.py; p.hidden = false;
    H.time = 0;
    H.updateInteraction();
    const kind = H.interactable && H.interactable.kind;
    H.interact();
    return { pass: kind === 'terminal' && H.level.lasersDisabledUntil >= H.time + 17, detail: `kind=${kind} until=${H.level.lasersDisabledUntil.toFixed(1)}` };
  });

  test('objective pickup activates extraction, exit completes mission', () => {
    H.startMission(1);
    const p = H.player;
    for (const o of H.level.objectives) {
      p.x = o.px; p.y = o.py; p.hidden = false;
      H.updateInteraction();
      const kind = H.interactable && H.interactable.kind;
      if (kind !== 'objective') return { pass: false, detail: `no objective prompt at ${o.name} (got ${kind})` };
      H.interact();
    }
    const objectivesDone = H.level.objectives.every((o) => o.collected);
    const exitLive = H.level.exit.active;
    p.x = H.level.exit.px; p.y = H.level.exit.py;
    H.updateInteraction();
    const kind = H.interactable && H.interactable.kind;
    H.interact();
    return { pass: objectivesDone && exitLive && kind === 'exit' && H.state === 'won', detail: `done=${objectivesDone} live=${exitLive} kind=${kind} state=${H.state}` };
  });

  test('alert reaching 100 fails the mission', () => {
    H.startMission(0);
    H.alert = 99;
    H.raiseAlert(5);
    return { pass: H.state === 'failed' && H.result && !H.result.success, detail: `state=${H.state} alert=${H.alert}` };
  });

  test('all five missions simulate cleanly', () => {
    const details = [];
    let pass = true;
    for (let i = 0; i < window.LEVELS.length; i++) {
      H.startMission(i);
      const l = H.level;
      const p = H.player;
      const spawnFloor = H.isFloorPx(p.x, p.y);
      const badGoal = l.objectives.some((o) => !H.isFloorPx(o.px, o.py));
      const badExit = !H.isFloorPx(l.exit.px, l.exit.py);
      p.hidden = true;
      let err = '';
      try {
        for (let k = 0; k < 120; k++) {
          H.time += 0.033;
          for (const g of l.guards) H.updateGuard(g, 0.033);
          for (const c of l.cameras) H.updateCamera(c, 0.033);
          H.updateLasers(0.033);
          H.updateAlert(0.033);
        }
      } catch (e) { err = e.message; }
      p.hidden = false;
      const ok = spawnFloor && !badGoal && !badExit && !err && H.state === 'playing';
      if (!ok) pass = false;
      details.push(`#${i + 1} spawn=${spawnFloor} obj=${!badGoal} exit=${!badExit} guards=${l.guards.length} cams=${l.cameras.length} lasers=${l.lasers.length} ${err || 'ok'}`);
    }
    return { pass, detail: details.join(' | ') };
  });

  H.startMission(0);
  return out;
});

let failures = 0;
for (const r of results) {
  if (!r.pass) failures++;
  console.log(`${r.pass ? 'PASS' : 'FAIL'}  ${r.name}${r.detail ? '  — ' + r.detail : ''}`);
}
console.log(`\n${results.length - failures}/${results.length} checks passed; pageerrors=${errors.length}`);
await browser.close();
process.exit(failures || errors.length ? 1 : 0);

