import { writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { createRequire } from 'node:module';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true, args: ['--disable-background-timer-throttling', '--disable-renderer-backgrounding'] });
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1, isMobile: true, hasTouch: true });
page.on('pageerror', e => console.log('PAGEERROR', e.message));
await page.goto('http://localhost:3000', { waitUntil: 'load' });
await page.waitForTimeout(1000);
const cdp = await page.context().newCDPSession(page);
const shot = async (name) => { const { data } = await cdp.send('Page.captureScreenshot', { format: 'png' }); writeFileSync(name, Buffer.from(data, 'base64')); console.log('shot', name); };
await shot('/tmp/mobile-menu.png');
await page.click('#deployBtn');
await page.waitForTimeout(4500);
await shot('/tmp/mobile-game.png');
await page.click('#touchPause');
await page.waitForTimeout(500);
await shot('/tmp/mobile-pause.png');
await browser.close();
